vim.keymap.set("n", "ZZ", "<CMD>qa<CR>", { desc = "Quit neovim", remap = false })
vim.keymap.set("n", "Q", "<CMD>bd<CR>", { desc = "Close and delete buffer", remap = false })
vim.keymap.set("n", "aj", "i<CR><ESC>", { desc = "Break line at cursor", remap = false })
vim.keymap.set("n", "<C-c>", "<CMD>nohlsearch<CR><CMD>NoiceDismiss<CR><CMD>lua for _, win in ipairs(vim.api.nvim_list_wins()) do local config = vim.api.nvim_win_get_config(win); if config.relative ~= '' then vim.api.nvim_win_close(win, false); print('Closing window', win) end end<CR>", { desc = "Toggle search highlight", remap = false })
vim.keymap.set("n", "<C-t><C-l>", "<CMD>tabnext<CR>", { desc = "Next tab", remap = false })
vim.keymap.set("n", "<C-t><C-h>", "<CMD>tabprevious<CR>", { desc = "Previous tab", remap = false })
vim.keymap.set("n", "<C-t><C-n>", "<CMD>tabnew<CR>", { desc = "New tab", remap = false })
vim.keymap.set("n", "<C-t><C-d>", "<CMD>tabclose<CR>", { desc = "Close tab", remap = false })
